import { chromium } from '@playwright/test'

const base = 'http://127.0.0.1:8199/'
const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()

// 列表页（学习园地）
await page.goto(base + 'index.html#/pages/portal/list/index?type=study', { waitUntil: 'networkidle' })
await page.waitForTimeout(1500)
// 检查是否有横向滚动条
const info = await page.evaluate(() => {
  const el = document.querySelector('.scroll-tabs')
  const tabsEls = document.querySelectorAll('.scroll-tab')
  const rects = Array.from(tabsEls).map(t => ({ text: t.textContent.trim(), left: Math.round(t.getBoundingClientRect().left), top: Math.round(t.getBoundingClientRect().top) }))
  return {
    hasScrollTabs: !!el,
    scrollWidth: el ? el.scrollWidth : null,
    clientWidth: el ? el.clientWidth : null,
    tabs: rects,
  }
})
console.log(JSON.stringify(info, null, 2))
await page.screenshot({ path: 'shot-list.png', fullPage: false })

// 首页
await page.goto(base + 'index.html#/pages/home/index', { waitUntil: 'networkidle' })
await page.waitForTimeout(1200)
const homeInfo = await page.evaluate(() => {
  const tabsEls = document.querySelectorAll('.scroll-tab')
  return Array.from(tabsEls).map(t => ({ text: t.textContent.trim(), top: Math.round(t.getBoundingClientRect().top) }))
})
console.log('HOME TABS', JSON.stringify(homeInfo))
await page.screenshot({ path: 'shot-home.png', fullPage: false })

await browser.close()

